// Filtrar ficheiros aceites: PDF + imagens (JPG/JPEG/PNG/GIF/WEBP)
const ficheiros = $input.first().json.value || [];
const EXTS = ['.pdf', '.jpg', '.jpeg', '.png', '.gif', '.webp'];

const validos = ficheiros.filter(f => {
  const nome = String(f.name || '').toLowerCase();
  return EXTS.some(e => nome.endsWith(e)) && f.file;
});

if (validos.length === 0) return [];

// Processar APENAS 1 fatura por poll (evita bug Loop SplitInBatches com múltiplas)
// A próxima fatura será processada no próximo poll (3min depois)
const ordenados = validos.slice().sort((a,b) => (a.createdDateTime||'').localeCompare(b.createdDateTime||''));
const primeiro = ordenados[0];
return [{
  json: {
    file_id: primeiro.id,
    file_name: primeiro.name,
    file_size: primeiro.size,
    created_at: primeiro.createdDateTime,
    total_na_pasta: validos.length
  }
}];

// Prepara body para Document AI (base64 do ficheiro + mime type)
const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const fileB64 = binaryBuffer.toString('base64');
const fileName = $('Loop Faturas').item.json.file_name || 'fatura.pdf';
const ext = String(fileName).toLowerCase().split('.').pop();
let mimeType = 'application/pdf';
if (ext === 'jpg' || ext === 'jpeg') mimeType = 'image/jpeg';
else if (ext === 'png') mimeType = 'image/png';
else if (ext === 'gif') mimeType = 'image/gif';
else if (ext === 'webp') mimeType = 'image/webp';

return [{ json: {
  body_docai: JSON.stringify({ rawDocument: { content: fileB64, mimeType: mimeType } }),
  file_name: fileName,
  file_id: $('Loop Faturas').item.json.file_id
} }];

// Parse resposta Google Document AI (formato entities + line_items)
const docaiResp = $input.first().json;
const doc = docaiResp?.document || {};
const entities = doc.entities || [];
const file_name = $('Loop Faturas').item.json.file_name;
const file_id = $('Loop Faturas').item.json.file_id;

function findEntity(type) {
  const e = entities.find(x => x.type === type);
  return e ? e.mentionText : null;
}

function normalizeNumber(s) {
  if (s === null || s === undefined || s === '') return 0;
  let str = String(s).trim().replace(/[€$\s]/g,'');
  // Formato PT: 1.910,45 -> 1910.45
  if (/^\d{1,3}(\.\d{3})+,\d+$/.test(str)) {
    str = str.replace(/\./g,'').replace(',','.');
  } else {
    str = str.replace(',','.');
  }
  const n = parseFloat(str);
  return isNaN(n) ? 0 : n;
}

function normalizeNif(s) {
  if (!s) return '';
  return String(s).trim().replace(/^PT\s*/i,'').replace(/\s+/g,'');
}

// Cabeçalho
const dados = {
  nif_fornecedor: normalizeNif(findEntity('supplier_tax_id')),
  nome_fornecedor: findEntity('supplier_name') || '',
  data_fatura: findEntity('invoice_date') || findEntity('due_date') || '',
  numero_fatura: findEntity('invoice_id') || '',
  numero_guia_remessa: null,
  desconto_global_percent: 0,
  total_sem_iva: normalizeNumber(findEntity('net_amount')),
  total_iva: normalizeNumber(findEntity('total_tax_amount')),
  total_com_iva: normalizeNumber(findEntity('total_amount')),
  tem_assinatura_recepcao: false,
  confianca: 'high'
};

// Line items
const lineItemEntities = entities.filter(e => e.type === 'line_item');
const linhas = lineItemEntities.map(li => {
  const props = li.properties || [];
  function prop(name) {
    const p = props.find(x => x.type === 'line_item/' + name);
    return p ? p.mentionText : null;
  }
  return {
    descricao: prop('description') || '',
    codigo_fornecedor: prop('product_code') || null,
    quantidade: normalizeNumber(prop('quantity')),
    unidade_original: prop('unit') || 'UN',
    preco_unitario: normalizeNumber(prop('unit_price')),
    desconto_percent: 0,
    taxa_iva: 23,
    total_linha_sem_iva: normalizeNumber(prop('amount')),
    total_linha_com_iva: normalizeNumber(prop('amount')) * 1.23
  };
});
dados.linhas = linhas;

// Validação NIF
const nifValido = /^\d{9}$/.test(dados.nif_fornecedor);

// Anomalias
const anomalias = [];
if (!nifValido) anomalias.push(`NIF invalido: ${dados.nif_fornecedor}`);
if (!dados.numero_fatura) anomalias.push('Sem numero de fatura');
if (linhas.length === 0) anomalias.push('Sem linhas de produto');

// Validacao totais
const somaLinhas = linhas.reduce((acc,l) => acc + (l.total_linha_sem_iva || 0), 0);
const diff = Math.abs(somaLinhas - dados.total_sem_iva);
const totaisOk = diff < 0.5;
// Divergência de totais NÃO bloqueia — Verificar EC Criado faz ajuste (1 placeholder ME003007 com total OCR)
// if (!totaisOk && dados.total_sem_iva > 0) {
//   anomalias.push(`Divergencia totais: linhas=${somaLinhas.toFixed(2)} vs total_sem_iva=${dados.total_sem_iva.toFixed(2)}`);
// }

const sucesso = anomalias.length === 0;

return [{
  json: {
    sucesso,
    erro: sucesso ? null : anomalias.join(' | '),
    file_id,
    file_name,
    dados_fatura: dados,
    anomalias,
    confianca: dados.confianca,
    nif_valido: nifValido,
    totais_ok: totaisOk,
    data_processamento: new Date().toISOString()
  }
}];

// Calcular ano e mes de destino a partir da data da fatura
// USA referencia explicita ao no original (evita depender de $json que pode nao ter dados_fatura)
const validado = $('Validar Receção').first();
const dados = validado?.json?.dados_fatura || {};
const dataFatura = dados.data_fatura || new Date().toISOString().substring(0, 10);
const partes = dataFatura.split('-');
const ano = partes[0] || new Date().getFullYear().toString();
const mes = partes[1] || String(new Date().getMonth() + 1).padStart(2, '0');

// Caminhos para a Graph API (Dep. com dois espacos precisa de encoding)
const baseEnc = 'Cabeceiras-PARTILHA/Dep.%20%20Financeiro/Automacao-tesouraria/Faturas/faturas%20inseridas';

return [{
  json: {
    ...validado.json,  // propaga tudo do validado (dados_fatura, anomalias, etc.)
    dest_ano: ano,
    dest_mes: mes,
    url_criar_ano: `https://graph.microsoft.com/v1.0/users/brandao@cabeceiras.pt/drive/items/01JSSR6ZLDQWWQPDGYP5CZJAQFOZUTJGI2/children`,
    url_criar_mes_path: `https://graph.microsoft.com/v1.0/users/brandao@cabeceiras.pt/drive/root:/${baseEnc}/${ano}:/children`,
    url_get_mes: `https://graph.microsoft.com/v1.0/users/brandao@cabeceiras.pt/drive/root:/${baseEnc}/${ano}/${mes}`,
    pasta_inseridas_id: '01JSSR6ZLDQWWQPDGYP5CZJAQFOZUTJGI2'
  }
}];

// Recolhe dados do log (versao robusta - usa first() em vez de item)
const parseNode = $('Validar Receção').first();
const destNode = $('Preparar Destino').first();
const ecNode = $('Verificar EC Criado').first();

const parse = parseNode?.json || {};
const dest = destNode?.json || {};
const ecData = ecNode?.json || {};
const dados = parse.dados_fatura || {};

const ecCriada = ecData?.ec_criada === true;
const ecNumero = ecData?.ec_numero || '';

const row = [
  parse.data_processamento || new Date().toISOString(),
  parse.file_name || '',
  String(dados.nif_fornecedor || ''),
  String(dados.nome_fornecedor || ''),
  String(dados.numero_fatura || ''),
  String(dados.data_fatura || ''),
  dados.total_com_iva != null ? dados.total_com_iva : '',
  String(parse.confianca || ''),
  (parse.anomalias || []).join(' | '),
  ecCriada ? 'Inserido BC' : 'Extraido',
  (dest.dest_ano || '') + '/' + (dest.dest_mes || ''),
  ecNumero
];

return [{ json: { payload: JSON.stringify({ values: [row] }) } }];

// Constrói payload para Log_Faturas: se já existe linha Anomalia dessa fatura, faz UPDATE; senão POST nova.
const parse = $json;
const dados = parse.dados_fatura || {};

const anomalias = parse.anomalias || [];
const nif = String(dados.nif_fornecedor || '').trim();
const numFat = String(dados.numero_fatura || '').toLowerCase().replace(/[\s\-\/]/g,'');

let tentativas = 1;
let existingIndex = null;
let existingRowState = '';
try {
  const logResp = $('Ler Log Excel').first().json;
  const rows = logResp?.value || [];
  for (const r of rows) {
    const v = r.values?.[0] || [];
    if (v.length < 10) continue;
    const nifLog = String(v[2] || '').trim();
    const numLog = String(v[4] || '').toLowerCase().replace(/[\s\-\/]/g,'');
    if (nifLog === nif && numLog === numFat && String(v[9]) === 'Anomalia') {
      tentativas++;
      if (existingIndex === null) {
        existingIndex = r.index;
        existingRowState = String(v[9]);
      }
    }
  }
} catch(e) {}

const moverParaErro = tentativas >= 3;
const anomMsg = anomalias.length > 0 ? anomalias.join(' | ') : (parse.erro || '');

const row = [
  parse.data_processamento || new Date().toISOString(),
  parse.file_name || '',
  String(dados.nif_fornecedor || ''),
  String(dados.nome_fornecedor || ''),
  String(dados.numero_fatura || ''),
  String(dados.data_fatura || ''),
  dados.total_com_iva != null ? dados.total_com_iva : '',
  String(parse.confianca || ''),
  anomMsg + ` (tentativa ${tentativas}/3)` + (moverParaErro ? ' - MOVIDA para faturas_com_erro' : ''),
  'Anomalia',
  '',
  ''
];

return [{
  json: {
    ...parse,
    payload: JSON.stringify({ values: [row] }),
    tentativas,
    mover_para_erro: moverParaErro,
    existing_row_index: existingIndex,
    is_update: existingIndex !== null
  }
}];

// Avalia AMBOS: existencia do fornecedor + duplicado da fatura no BC
// AGORA tambem verifica EC ja existente em Open (nao apenas ledger entries)
const parse = $('Verificar Duplicado Local').item.json;
const bcDup = $('Verificar Duplicado BC').first().json;
const bcVendor = $input.first().json;

const anomalias = [...(parse.anomalias || [])];

// 1. Verificar fornecedor por NIF
const vendors = bcVendor?.value || [];
let vendor_no = null;
let vendor_blocked = false;

// Match PERFEITO obrigatório: NIF exato OU (na ausência) 1 único match de nome
function normalizeName(s) {
  return String(s || '').trim().toUpperCase()
    .replace(/[.,;:()]/g,'')
    .replace(/\s+/g,' ')
    .replace(/\bLDA\b|\bLIMITADA\b|\bS\.?A\b|\bUNIPESSOAL\b/g,'')
    .trim();
}

const nifFatura = String(parse.dados_fatura.nif_fornecedor || '').trim();
const nomeFatura = normalizeName(parse.dados_fatura.nome_fornecedor);

async function findByName() {
  // Extrair primeira palavra significativa do nome (>3 chars)
  const words = String(parse.dados_fatura.nome_fornecedor || '').split(/[\s,.]+/).filter(w => w.length > 3);
  if (words.length === 0) return [];
  const searchTerm = words[0].toUpperCase();
  const url = `https://api.businesscentral.dynamics.com/v2.0/f41c8222-df66-449c-93b5-c1879e641cb2/PROD/ODataV4/Company('Jorge%20Brand%C3%A3o%20Gon%C3%A7alves')/workflowVendors?$filter=contains(name,'${searchTerm}')&$select=number,name,vatRegistrationNumber,blocked`;
  const token = $('Obter Token BC').first().json.access_token;
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: url,
      headers: { 'Authorization': `Bearer ${token}` },
      json: true
    });
    return resp?.value || [];
  } catch(e) {
    return [];
  }
}

let matchType = null;
// Regra 1: match perfeito de NIF via primeira query
let match = vendors.find(x => String(x.vatRegistrationNumber||'').trim() === nifFatura);
if (match) matchType = 'NIF';

// Regra 2: se NIF falhou, procurar por NOME no BC
if (!match) {
  const nameVendors = await findByName();
  const exactMatches = nameVendors.filter(x => normalizeName(x.name) === nomeFatura);
  if (exactMatches.length === 1) {
    match = exactMatches[0];
    matchType = 'nome exato';
  } else if (exactMatches.length > 1) {
    anomalias.push(`AMBIGUIDADE: ${exactMatches.length} fornecedores com nome '${parse.dados_fatura.nome_fornecedor}' no BC. NIF ${nifFatura} nao existe. Jorge decide manualmente.`);
  } else if (nameVendors.length > 0) {
    const opcoes = nameVendors.map(x => `${x.number} ${x.name}`).join(' | ');
    anomalias.push(`AMBIGUIDADE: NIF ${nifFatura} nao existe no BC. Nome '${parse.dados_fatura.nome_fornecedor}' nao bate exatamente. Candidatos parciais: ${opcoes}`);
  } else {
    anomalias.push(`Fornecedor NIF ${nifFatura} e nome '${parse.dados_fatura.nome_fornecedor}' nao existem no BC`);
  }
}

if (match) {
  vendor_no = match.number;
  vendor_blocked = String(match.blocked || '').trim() !== '';
  if (vendor_blocked) {
    anomalias.push(`Fornecedor ${vendor_no} (${match.name}) esta BLOQUEADO no BC (blocked=${match.blocked})`);
  }
}

// 2. Verificar duplicado da fatura em VendorLedgerEntries (POs registadas)
const entriesRaw = bcDup?.value || [];
// Filtrar duplicados APENAS do mesmo vendor (mesmo numero de fatura pode existir em vendors diferentes)
const entries = vendor_no ? entriesRaw.filter(e => String(e.Vendor_No||'').trim() === vendor_no) : [];
let bc_duplicado = false;
let bc_doc_no = null;

if (entries.length > 0) {
  bc_duplicado = true;
  bc_doc_no = entries[0].Document_No;
  anomalias.push(`Duplicado no BC (Ledger): fatura ja registada como ${bc_doc_no} (vendor: ${entries[0].Vendor_Name})`);
}

const sucesso = anomalias.length === 0 && parse.confianca !== 'low';

// Sobrescrever nome_fornecedor pelo do BC (fonte de verdade — Document AI pode trocar comprador↔vendedor)
const dadosFatOverride = { ...(parse.dados_fatura || {}) };
if (match && match.name) {
  dadosFatOverride.nome_fornecedor_ocr = dadosFatOverride.nome_fornecedor;  // preserva original
  dadosFatOverride.nome_fornecedor = String(match.name).trim();
}

return [{
  json: {
    ...parse,
    dados_fatura: dadosFatOverride,
    anomalias,
    sucesso,
    bc_verificado: true,
    bc_vendor_no: vendor_no,
    bc_vendor_name: match ? match.name : null,
    bc_vendor_blocked: vendor_blocked,
    bc_vendor_found: vendors.length > 0,
    bc_duplicado,
    bc_doc_no,
    bc_entries_found: entries.length
  }
}];

// Validar recepcao (Fase 4 melhorada): identifica guia por nome + prepara verificacao Claude
const avaliado = $('Avaliar Resultado BC').item.json;
const guiasResp = $input.first().json;
const guiasFiles = guiasResp?.value || [];

const dados = avaliado.dados_fatura || {};
const numGuia = String(dados.numero_guia_remessa || '').trim();
// Ler tem_assinatura do Merge Assinatura (onde GPT validou) — fallback: dados.tem_assinatura_recepcao
let temAssinatura = false;
try {
  const merge = $('Merge Assinatura').first().json;
  temAssinatura = merge?.dados_fatura?.tem_assinatura_recepcao === true;
} catch(e) {
  temAssinatura = dados.tem_assinatura_recepcao === true;
}
const anomalias = [...(avaliado.anomalias || [])];

// Procurar ficheiro na pasta com match por numero de guia
let guiaFile = null;
if (numGuia && numGuia !== 'null' && numGuia !== '') {
  const numGuiaNorm = numGuia.toLowerCase().replace(/[\s\-\/]/g, '');
  for (const f of guiasFiles) {
    const fname = String(f.name || '').toLowerCase().replace(/[\s\-\/]/g, '');
    if (fname.includes(numGuiaNorm)) {
      guiaFile = { id: f.id, name: f.name };
      break;
    }
  }
}

// Procurar por numero de fatura tambem (caso fatura assinada esteja nesta pasta)
let faturaAssinadaFile = null;
const numFatura = String(dados.numero_fatura || '').toLowerCase().replace(/[\s\-\/]/g, '').replace(/^ft/,'').replace(/^nc/,'');
if (numFatura) {
  for (const f of guiasFiles) {
    const fname = String(f.name || '').toLowerCase().replace(/[\s\-\/]/g, '');
    if (fname.includes(numFatura)) {
      faturaAssinadaFile = { id: f.id, name: f.name };
      break;
    }
  }
}

// Decisao: precisa verificar guia com Claude?
// Prioridade: 1) fatura ja tem assinatura (skip Claude) 2) guia encontrada (verifica com Claude) 3) nada (anomalia)
let precisaVerificarClaude = false;
let ficheiroParaVerificar = null;

if (temAssinatura) {
  // Passa direto: fatura ja tem assinatura visivel
  precisaVerificarClaude = false;
} else if (guiaFile) {
  // Precisa Claude verificar assinatura na guia
  precisaVerificarClaude = true;
  ficheiroParaVerificar = guiaFile;
} else if (faturaAssinadaFile) {
  // Fatura assinada em pasta separada
  precisaVerificarClaude = true;
  ficheiroParaVerificar = faturaAssinadaFile;
} else {
  // Nenhuma prova - anomalia imediata
  precisaVerificarClaude = false;
  let msg = 'Sem prova de recepcao: ';
  const detalhes = [];
  detalhes.push('fatura sem assinatura');
  if (numGuia) detalhes.push(`guia ${numGuia} nao encontrada em Guia ou Fatura Assinadas`);
  else detalhes.push('fatura sem numero de guia');
  msg += detalhes.join('; ');
  anomalias.push(msg);
}

return [{
  json: {
    ...avaliado,
    anomalias,
    precisa_verificar_claude: precisaVerificarClaude,
    precisa_verificar_claude_count: precisaVerificarClaude ? 1 : 0,
    ficheiro_para_verificar_id: ficheiroParaVerificar?.id || null,
    ficheiro_para_verificar_nome: ficheiroParaVerificar?.name || null,
    prova_assinatura_fatura: temAssinatura,
    prova_guia_ficheiro: guiaFile?.name || null,
    prova_fatura_assinada_ficheiro: faturaAssinadaFile?.name || null,
    recepcao_validada: temAssinatura  // apenas se ja tem assinatura na fatura; senao aguarda Claude
  }
}];

// Verifica duplicado no Excel log e devolve flag (nao adiciona anomalia)
const parse = $('Parse e Validar').item.json;
const logResp = $input.first().json;
const rows = logResp?.value || [];

const dados = parse.dados_fatura || {};
const nifAtual = String(dados.nif_fornecedor || '').trim();
const numFaturaAtual = String(dados.numero_fatura || '').toLowerCase().replace(/[\s\-\/]/g, '');

let duplicadoLocal = null;

for (const r of rows) {
  const v = r.values?.[0] || [];
  if (v.length < 5) continue;

  const nifLog = String(v[2] || '').trim();
  const numLog = String(v[4] || '').toLowerCase().replace(/[\s\-\/]/g, '');
  const estadoLog = String(v[9] || '').trim();

  if (nifLog && nifAtual && nifLog === nifAtual && numLog && numLog === numFaturaAtual && estadoLog !== 'ERRO' && estadoLog !== 'Anomalia') {
    duplicadoLocal = {
      data_log: v[0],
      file_name_log: v[1],
      estado_log: estadoLog
    };
    break;
  }
}

return [{
  json: {
    ...parse,
    duplicado_local: duplicadoLocal !== null,
    duplicado_local_count: duplicadoLocal !== null ? 1 : 0,
    duplicado_local_info: duplicadoLocal
  }
}];

// Prepara payload da EC — MANTEM "FT " no invoice number + adiciona AUTOMAÇÃO
const data = $('Validar Receção').first().json;
const dados = data.dados_fatura || {};

// Ler CCusto do Excel (via Aplicar Mapeamento Excel) — Jorge: conforme o Excel
let centroCusto = '';
try {
  const mapExcel = $('Aplicar Mapeamento Excel').first().json;
  centroCusto = String(mapExcel.centro_custo_default || '').trim();
} catch(e) { centroCusto = ''; }

// Calcular divergência total (previsto pelas linhas vs OCR)
const descontoGlobal = Number(dados.desconto_global_percent) || 0;
const totalPrevisto = (dados.linhas || []).reduce((acc, l) => {
  const desc = Number(l.desconto_percent) || 0;
  const efetivo = desc > 0 ? desc : descontoGlobal;
  const qty = Number(l.quantidade) || 0;
  const pu = Number(l.preco_unitario) || 0;
  const iva = Number(l.taxa_iva) || 0;
  const semIva = qty * pu * (1 - efetivo/100);
  return acc + semIva * (1 + iva/100);
}, 0);
const totalFatura = Number(dados.total_com_iva) || 0;
const diffValor = Math.abs(totalPrevisto - totalFatura);
const divergenciaValores = (diffValor > 0.50 && totalFatura > 0);

// Deteta se alguma linha ficou com ME003007 (placeholder) — item sem match no BC
const temItemSemMatch = (dados.linhas || []).some(l => String(l.codigo_bc_mapeado || '') === 'ME003007');

// postingDescription combinado
let marcasFlag = 'AUTOMAÇÃO';
if (divergenciaValores) marcasFlag += ' - ATENÇÃO VALORES';
if (temItemSemMatch) marcasFlag += ' - ITEM SEM MATCH';

// Sempre "FT " prefixo (Jorge: evita colisões no BC). Se já tem prefixo (FT/NC/FR/GT/GS/GR/VD), mantém.
let numFatura = String(dados.numero_fatura || '').trim();
if (numFatura && !/^(FT|FAT|NC|FR|FRA|FC|FS|FE|GT|GS|GR|VD)\s/i.test(numFatura)) {
  numFatura = 'FT ' + numFatura;
}

const orderDate = dados.data_fatura || new Date().toISOString().substring(0, 10);

const header = {
  documentType: 'Order',
  buyFromVendorNumber: data.bc_vendor_no,
  vendorInvoiceNumber: numFatura,
  orderDate: orderDate,
  postingDate: orderDate,
  documentDate: orderDate,
  locationCode: 'P1',
  postingDescription: marcasFlag,  // marca combinada: AUTOMAÇÃO + ATENÇÃO VALORES + ITEM SEM MATCH conforme aplicável
  shortcutDimension1Code: centroCusto  // Centro Custo do Excel Codigos Fornecedores col.5 (Jorge)
};

// Divergência já marca postingDescription 'ATENÇÃO VALORES' + Verificar EC Criado vai ajustar linhas
// para 1 placeholder ME003007 com total_sem_iva (usa total OCR que está certo)
return [{
  json: {
    ...data,
    ec_header_payload: JSON.stringify(header),
    divergencia_valores: divergenciaValores,
    divergencia_bloqueia: false,
    tem_item_sem_match: temItemSemMatch,
    marcasFlag: marcasFlag,
    total_fatura: totalFatura,
    total_previsto: totalPrevisto,
    diff_valor: diffValor
  }
}];

// Prepara linhas para inserir (usa mapping do Excel ou do Claude)
// Fonte robusta: tenta Aplicar Mapeamento (fallback OpenAI); se não correu, cai para Aplicar Mapeamento Excel
let data;
try {
  data = $('Aplicar Mapeamento').first().json;
} catch (e) {
  data = $('Aplicar Mapeamento Excel').first().json;
}
const ecHeader = $('Criar EC Header BC PROD').first().json;

const ecNumber = ecHeader?.number;
const erro = ecHeader?.error?.message;
const anomalias = [...(data.anomalias || [])];

if (!ecNumber || erro) {
  anomalias.push(`Falha a criar EC no BC: ${erro || 'sem numero devolvido'}`);
  return [{ json: { ...data, anomalias, ec_criada: false, ec_criada_count: 0, ec_erro: erro || 'sem numero', linhas_para_criar: [] } }];
}

// Descontos: prioridade por linha, fallback cabecalho global
const descontoGlobal = Number(data.dados_fatura?.desconto_global_percent) || 0;
const ccustoDefault = ($('Aplicar Mapeamento Excel').first().json || {}).centro_custo_default || '';

// As linhas ja tem codigo_bc_mapeado (do Excel ou OpenAI)
const linhas = (data.dados_fatura?.linhas || []).map((linha, idx) => {
  const codigoItem = linha.codigo_bc_mapeado || 'ME003007';
  const descLinha = Number(linha.desconto_percent) || 0;
  const descontoAplicar = descLinha > 0 ? descLinha : descontoGlobal;
  return {
    payload: {
      documentType: 'Order',
      documentNumber: ecNumber,
      lineNumber: (idx + 1) * 10000,
      type: 'Item',
      number: codigoItem,
      description: String(linha.descricao || '').substring(0, 100),
      quantity: Number(linha.quantidade) || 0,
      directUnitCost: Number(linha.preco_unitario) || 0,
      locationCode: 'P1',
      shortcutDimension1Code: linha.centro_custo || ccustoDefault,
      lineDiscountPercent: descontoAplicar
    }
  };
});

// Divergência é calculada no Preparar EC Header (antes do POST)

if (linhas.length === 0) {
  return [{ json: { ...data, ec_criada: true, ec_criada_count: 1, ec_numero: ecNumber, linhas_para_criar: [], no_lines: true, line_payload: '{}' } }];
}

return linhas.map(l => ({
  json: { ec_criada: true, ec_criada_count: 1, ec_numero: ecNumber, line_payload: JSON.stringify(l.payload), parent_data: data }
}));

const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const pdfBase64 = binaryBuffer.toString('base64');

const validacao = $('Validar Receção').item.json;
const nomeFicheiro = validacao.ficheiro_para_verificar_nome || '';

const prompt = `Analisa este documento (guia de remessa ou fatura assinada) e responde APENAS com JSON.

Ficheiro: ${nomeFicheiro}

Verifica se ha PROVA DE RECEPCAO/ENTREGA visivel:
- Assinatura manuscrita
- Carimbo "DIGITALIZADO", "Recebido", "Entregue", "Conferido"
- Data de entrega manuscrita
- Rubrica com data

Ignora assinaturas ou carimbos digitais impressos que fazem parte do template.

Formato (so JSON):
{
  "tem_prova_recepcao": true ou false,
  "tipo_prova": "assinatura_manual" | "carimbo" | "texto_manuscrito" | "nenhum",
  "descricao": "string curta"
}`;

// Deteta tipo pelo nome do ficheiro (PDF vs imagem)
const extG = String(nomeFicheiro || '').toLowerCase().split('.').pop();
let contentItemG;
if (extG === 'pdf') {
  contentItemG = { type: 'file', file: { filename: nomeFicheiro || 'guia.pdf', file_data: `data:application/pdf;base64,${pdfBase64}` } };
} else {
  const mimeG = extG === 'png' ? 'image/png'
              : extG === 'gif' ? 'image/gif'
              : extG === 'webp' ? 'image/webp'
              : 'image/jpeg';
  contentItemG = { type: 'image_url', image_url: { url: `data:${mimeG};base64,${pdfBase64}`, detail: 'high' } };
}

const payload = {
  model: 'gpt-4o-2024-11-20',
  max_tokens: 512,
  messages: [{
    role: 'user',
    content: [
      contentItemG,
      { type: 'text', text: prompt }
    ]
  }]
};

return [{ json: { claude_payload: JSON.stringify(payload), nome_ficheiro: nomeFicheiro } }];

// Parse resposta Claude e decide se ha prova real de recepcao
const validacao = $('Validar Receção').item.json;
const openaiResp = $input.first().json;
const anomalias = [...(validacao.anomalias || [])];

const textContent = openaiResp?.choices?.[0]?.message?.content || '';

let claudeVer = { tem_prova_recepcao: false, tipo_prova: 'nenhum', descricao: 'Erro no parse Claude' };
try {
  const jsonStr = textContent.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/i,'').trim();
  claudeVer = JSON.parse(jsonStr);
} catch(e) {
  anomalias.push(`Falha a analisar resposta Claude (guia): ${e.message}`);
}

const temProva = claudeVer.tem_prova_recepcao === true;
const nomeFich = validacao.ficheiro_para_verificar_nome || 'desconhecido';

if (!temProva) {
  anomalias.push(`Guia ${nomeFich} SEM prova visivel de recepcao (Claude: ${claudeVer.descricao || 'sem detalhes'})`);
}

return [{
  json: {
    ...validacao,
