  }
}];

// Verifica se ja existe EC em Open com o mesmo vendorInvoiceNumber
const avaliado = $('Avaliar Resultado BC').item.json;
const resp = $input.first().json;
const ecs = resp?.value || [];

const anomalias = [...(avaliado.anomalias || [])];

if (ecs.length > 0) {
  const existente = ecs[0];
  anomalias.push(`EC ja existe no BC (Open): ${existente.number} para invoice ${existente.vendorInvoiceNumber}`);
}

const sucesso = anomalias.length === 0 && avaliado.confianca !== 'low';

return [{
  json: {
    ...avaliado,
    anomalias,
