  }
}];

// Prompt Claude SEM preço, foco em família + dimensão + descrição
const validado = $('Aplicar Mapeamento Excel').first().json;
const itemsResp = $input.first().json;
const items = itemsResp?.value || [];
const dados = validado.dados_fatura || {};
const linhas = dados.linhas || [];
const linhasSemMatch = linhas.filter(l => l.precisa_claude);

if (items.length === 0 || linhasSemMatch.length === 0) {
  return [{ json: { skip_mapping: true, reason: 'sem items ou sem linhas por mapear', linhas_originais: linhas } }];
}

const itemsCatalogo = items.slice(0, 300).map(it => ({
  codigo: it.number,
  descricao: it.description || ''
}));

const linhasParaMapear = linhasSemMatch.map(l => ({
  index: l.linha_index,
  descricao: l.descricao || '',
  codigo_fornecedor: l.codigo_fornecedor || null,
  unidade: l.unidade_original || ''
}));

const prompt = `Corresponde linhas de fatura ao catalogo BC baseado APENAS em DESCRICAO (não usar preço).

REGRAS:
1. Se PRODUTO EXISTE no catalogo → devolve codigo BC
2. Se NAO EXISTE → devolve null

CRITERIOS (só descrição):
- Familia: nome principal (Kappiton, Colchao, Sommier)
- Dimensao: mesmos numeros; dimensoes invertidas correspondem (200x90 = 90x200); ignorar espessura (200x90x22 -> 90x200)
- Sufixos comerciais IRRELEVANTES: ECO, PRO, AeroFlow, HYBRID, PLUS, ELITE

Se DOIS itens BC batem por familia+dimensao com uma linha, escolhe o que tem descricao mais proxima (sem usar preço).

Descricoes IDENTICAS entre linhas da fatura DEVEM mapear ao MESMO codigo BC.

CATALOGO BC (${itemsCatalogo.length} items):
${JSON.stringify(itemsCatalogo, null, 1)}

LINHAS FATURA para mapear (${linhasParaMapear.length}):
${JSON.stringify(linhasParaMapear, null, 1)}

Responde SO JSON:
{
  "matches": [
    { "linha_index": 0, "codigo_bc": "MEXXXXXX" ou null, "razao": "explicacao curta" }
  ]
}

Nao inventes codigos. So devolve codigos do catalogo.`;

const payload = {
  model: 'gpt-4o-2024-11-20',
  max_tokens: 4096,
  messages: [{ role: 'user', content: prompt }]
};

return [{
  json: {
    skip_mapping: false,
    claude_payload: JSON.stringify(payload),
    linhas_completas: linhas,
    catalogo_codigos: itemsCatalogo.map(i => i.codigo),
    nif_fornecedor: validado.nif_fornecedor
  }
}];

// Aplica mapeamento Claude (só descrição, sem preço) + prepara novas linhas para Excel
const PLACEHOLDER = 'ME003007';

const prep = $('Preparar Payload Claude Items').first().json;
const openaiResp = $input.first().json;
const validado = $('Aplicar Mapeamento Excel').first().json;

const linhas = prep?.linhas_completas || validado.dados_fatura?.linhas || [];
const catalogo = new Set(prep?.catalogo_codigos || []);
const nifFornecedor = prep?.nif_fornecedor || validado.nif_fornecedor;

if (prep?.skip_mapping) {
  // Aplicar placeholder às linhas sem match E também registar codigo_fornecedor no Excel (Codigo ERP vazio, Jorge preenche depois)
  const linhasFinal = linhas.map(l => l.precisa_claude ? { ...l, codigo_bc_mapeado: PLACEHOLDER, mapping_fonte: 'placeholder' } : l);
  const dados = { ...(validado.dados_fatura || {}), linhas: linhasFinal };

  // Auto-popular Excel: extrair PKs únicos das linhas que precisavam Claude e têm codigo_fornecedor
  const seenPK = new Set();
  const novasLinhasExcel = [];
  for (const l of linhas) {
    if (!l.precisa_claude) continue;
    const pk = String(l.codigo_fornecedor || '').replace(/[\s\u00a0]/g,'').toUpperCase();
    if (!pk || seenPK.has(pk)) continue;
    seenPK.add(pk);
    novasLinhasExcel.push({
      bc_vendor_no: validado.bc_vendor_no || '',
      nome: validado.dados_fatura?.nome_fornecedor || '',
      codigo_fornecedor: l.codigo_fornecedor,
      codigo_erp: '',
      centro_custo: (validado.centro_custo_default || '')
    });
  }
  return [{ json: { ...validado, dados_fatura: dados, novas_linhas_excel: novasLinhasExcel } }];
}

// Parse Claude
const textContent = openaiResp?.choices?.[0]?.message?.content || '';
let claudeData = { matches: [] };
try {
  let jsonStr = textContent;
  const blockMatch = textContent.match(/```json\s*([\s\S]*?)\s*```/);
  if (blockMatch) jsonStr = blockMatch[1];
  else {
    const braceMatch = textContent.match(/\{[\s\S]*\}/);
    if (braceMatch) jsonStr = braceMatch[0];
  }
  claudeData = JSON.parse(jsonStr.trim());
} catch(e) {
  // Fallback: placeholder para todas
  const linhasFinal = linhas.map(l => l.precisa_claude ? { ...l, codigo_bc_mapeado: PLACEHOLDER, mapping_fonte: 'openai-parse-fail' } : l);
  const dados = { ...(validado.dados_fatura || {}), linhas: linhasFinal };
  return [{ json: { ...validado, dados_fatura: dados, novas_linhas_excel: [] } }];
}

// Aplicar matches por linha_index
const matchesByIndex = {};
for (const m of (claudeData.matches || [])) matchesByIndex[m.linha_index] = m;

const novasLinhasExcel = [];  // vao ser adicionadas ao Excel
const seenPK = new Set();

const linhasFinal = linhas.map((l, idx) => {
  if (!l.precisa_claude) return l;  // já tem match do Excel

  const match = matchesByIndex[idx];
  const codigo = match?.codigo_bc;

  if (codigo && codigo !== 'null' && codigo !== '' && catalogo.has(codigo)) {
    // Match Claude válido — adicionar ao Excel se PK existe e é único
    const pk = String(l.codigo_fornecedor || '').replace(/[\s\u00a0]/g,'').toUpperCase();
    if (pk && !seenPK.has(pk)) {
      seenPK.add(pk);
      novasLinhasExcel.push({
        bc_vendor_no: validado.bc_vendor_no || '',
        nome: validado.dados_fatura?.nome_fornecedor || '',
        codigo_fornecedor: l.codigo_fornecedor,
        codigo_erp: codigo,
        centro_custo: (validado.centro_custo_default || '')
      });
    }
    return {
      ...l,
      codigo_bc_mapeado: codigo,
      mapping_fonte: 'openai',
      mapping_razao: match?.razao || 'match claude'
    };
  }

  // Não match → placeholder
  return { ...l, codigo_bc_mapeado: PLACEHOLDER, mapping_fonte: 'placeholder' };
});

const dados = { ...(validado.dados_fatura || {}), linhas: linhasFinal };
const estatisticas = {
  total: linhas.length,
  match_excel: linhas.filter(l => !l.precisa_claude).length,
  match_claude: novasLinhasExcel.length,
  placeholder: linhasFinal.filter(l => l.codigo_bc_mapeado === PLACEHOLDER).length
};

return [{
  json: {
    ...validado,
    dados_fatura: dados,
    mapping_estatisticas: estatisticas,
    novas_linhas_excel: novasLinhasExcel
  }
}];

// Match direto NIF+PK no Excel Codigos Fornecedores
const validado = $('Validar Receção').first().json;
const cfResp = $('Ler Excel Codigos Fornecedores').first().json;
const rows = cfResp?.value || [];
const dados = validado.dados_fatura || {};
const bcVendorNo = String(validado.bc_vendor_no || '').trim();  // F00001, F00290...

// Construir mapa (NIF + PK normalizado) -> Codigo ERP
function normPK(s) { return String(s || '').replace(/[\s\u00a0]/g,'').toUpperCase(); }
const mapaExcel = {};
const ccustoPorFornecedor = {};  // bc_vendor_no -> centro_custo default
for (const r of rows) {
  const v = r.values?.[0] || [];
  if (v.length < 4) continue;
  const bcVendorExcel = String(v[0] || '').trim();  // Numero Fornecedor BC (F00001)
  const pkExcel = normPK(v[2]);                     // Codigo Fornecedor
  const codigoErp = String(v[3] || '').trim();      // Codigo ERP
  const ccusto = v.length >= 5 && v[4] !== null && v[4] !== '' ? String(v[4]).trim() : '';
  if (bcVendorExcel && pkExcel && codigoErp) {
    mapaExcel[`${bcVendorExcel}|${pkExcel}`] = { codigo: codigoErp, ccusto };
  }
  if (bcVendorExcel && ccusto && !ccustoPorFornecedor[bcVendorExcel]) {
    ccustoPorFornecedor[bcVendorExcel] = ccusto;
  }
}

// Também mapa descrição -> código (para garantir L2/L4 iguais)
const mapaDescricao = {};

// Aplicar match a cada linha da fatura
const linhas = (dados.linhas || []).map((l, idx) => {
  const pkFatura = normPK(l.codigo_fornecedor);
  const descricao = String(l.descricao || '').trim();
  const key = `${bcVendorNo}|${pkFatura}`;

  // 1. Match direto Excel
  if (pkFatura && mapaExcel[key]) {
    const entry = mapaExcel[key];
    const codigo = entry.codigo;
    if (codigo && codigo !== '' && codigo !== 'ME003007') {
      // Excel tem Codigo ERP real — usar
      mapaDescricao[descricao] = codigo;
      return {
        ...l,
        codigo_bc_mapeado: codigo,
        centro_custo: entry.ccusto || '',
        mapping_fonte: 'excel',
        mapping_razao: `Excel: BC ${bcVendorNo} + PK ${pkFatura} -> ${codigo}`,
        precisa_claude: false
      };
    } else {
      // Excel tem linha mas Codigo ERP vazio (aguarda Jorge preencher) — usa placeholder sem chamar Claude
      return {
        ...l,
        codigo_bc_mapeado: 'ME003007',
        centro_custo: entry.ccusto || '',
        mapping_fonte: 'excel-pendente',
        mapping_razao: `Excel: BC ${bcVendorNo} + PK ${pkFatura} aguarda cadastro (Codigo ERP vazio)`,
        precisa_claude: false
      };
    }
  }

  // 2. Descrição idêntica a outra linha já mapeada (por Excel)
  if (mapaDescricao[descricao]) {
    return {
      ...l,
      codigo_bc_mapeado: mapaDescricao[descricao],
      centro_custo: ccustoPorFornecedor[bcVendorNo] || '',
      mapping_fonte: 'excel-descricao',
      mapping_razao: `Descrição idêntica a outra linha`,
      precisa_claude: false
    };
  }

  // 3. Não encontrou → marcar para Claude tentar (ou ME003007 no final)
  return {
    ...l,
    codigo_bc_mapeado: null,
    precisa_claude: true,
    linha_index: idx
  };
});

const semMatch = linhas.filter(l => l.precisa_claude);
const dadosOut = { ...dados, linhas };

// CCusto default do fornecedor (do Excel) — usado para header + linhas OpenAI + PATCH
const centroCustoDefault = ccustoPorFornecedor[bcVendorNo] || '';

return [{
  json: {
    ...validado,
    dados_fatura: dadosOut,
    total_linhas_fatura: linhas.length,
    linhas_com_match_excel: linhas.length - semMatch.length,
    linhas_sem_match: semMatch.length,
    precisa_claude_count: semMatch.length > 0 ? 1 : 0,
    bc_vendor_no: bcVendorNo,
    centro_custo_default: centroCustoDefault,
    _debug_rows_count: rows.length,
    _debug_ccusto_map: ccustoPorFornecedor,
    _debug_sample_row: rows[0] ? { v_length: (rows[0].values?.[0]||[]).length, v: rows[0].values?.[0], typeof_v4: typeof (rows[0].values?.[0]||[])[4] } : null
  }
}];

// Adiciona novas linhas descobertas ao Excel Codigos Fornecedores (uma POST por linha)
// DEDUP: só adiciona (bcVendor+PK) que ainda não estejam no Excel atual
const validado = $input.first().json;
let novas = validado.novas_linhas_excel || [];

// Excel atual lido antes (via Ler Excel Codigos Fornecedores)
try {
  const cfResp = $('Ler Excel Codigos Fornecedores').first().json;
  const rows = cfResp?.value || [];
  const existentes = new Set();
  const normPK = s => String(s||'').replace(/[\s\u00a0]/g,'').toUpperCase();
  for (const r of rows) {
    const v = r.values?.[0] || [];
    const bcVendor = String(v[0]||'').trim();
    const pk = normPK(v[2]);
    if (bcVendor && pk) existentes.add(`${bcVendor}|${pk}`);
  }
  novas = novas.filter(l => {
    const key = `${l.bc_vendor_no}|${normPK(l.codigo_fornecedor)}`;
    return !existentes.has(key);
  });
} catch(e) {}

if (novas.length === 0) {
  return [{ json: { ...validado, excel_adicionado: 0, values_payload: '{"values":[]}', skip_excel_post: true } }];
}

// Preparar payloads para chamadas HTTP
// (n8n Code nao faz HTTP; retorna cada linha como item para nó HTTP a jusante)
const items = novas.map(l => ({
  json: {
    parent_data: validado,
    values_payload: JSON.stringify({
      values: [[l.bc_vendor_no, l.nome, l.codigo_fornecedor, l.codigo_erp, l.centro_custo || '']]
    })
  }
}));

// Guardar um marcador em cada item para depois consolidar
return items;

// Prepara body OpenAI para verificar assinatura na fatura
const parseData = $input.first().json;

// Buscar binary do Download PDF (nó anterior no fluxo, tem o binary original)
const downloadItems = $('Download PDF').all();
// Encontrar o item cujo file_id corresponde
let binaryData = null;
for (const it of downloadItems) {
  if (it.binary && it.binary.data) {
    binaryData = it.binary.data;
    break;
  }
}

let fileB64 = '';
let mimeType = 'application/pdf';
const fileName = parseData.file_name || 'fatura.pdf';
const ext = String(fileName).toLowerCase().split('.').pop();
if (ext === 'jpg' || ext === 'jpeg') mimeType = 'image/jpeg';
else if (ext === 'png') mimeType = 'image/png';

if (binaryData && binaryData.data) {
  fileB64 = binaryData.data;  // já em base64
} else {
  // fallback: tentar via helpers
  try {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
    fileB64 = buf.toString('base64');
  } catch(e) {
    // Se falhar, saltar verificação — retorna como true (assumir OK)
    return [{ json: {
      gpt_payload: JSON.stringify({ model: 'gpt-4o', max_tokens: 10, messages: [{role:'user',content:'skip'}] }),
      parse_data: parseData,
      skip_gpt: true
    } }];
  }
}

const prompt = `Analisa esta fatura de fornecedor. Responde APENAS com JSON valido:
{"tem_assinatura_recepcao": boolean, "razao": "string curta"}

Verifica se ha PROVA DE RECEPCAO visivel:
- Carimbo "DIGITALIZADO" (novo carimbo Cabeceiras)
- Assinatura manuscrita/rubrica
- Marca de "Recebido", "Entregue", "Conferido"
- Data manuscrita de entrega

Ignora assinaturas/carimbos digitais impressos que fazem parte do template.`;

let contentItem;
if (ext === 'pdf') {
  contentItem = { type: 'file', file: { filename: fileName, file_data: `data:application/pdf;base64,${fileB64}` } };
} else {
  contentItem = { type: 'image_url', image_url: { url: `data:${mimeType};base64,${fileB64}` } };
}

const payload = {
  model: 'gpt-4o',
  max_tokens: 200,
  messages: [{ role: 'user', content: [contentItem, { type: 'text', text: prompt }] }]
};

return [{ json: {
  gpt_payload: JSON.stringify(payload),
  parse_data: parseData,
  skip_gpt: false
} }];

// Merge resultado GPT com dados do Parse e Validar
const gptResp = $input.first().json;
const prev = $('Preparar Payload GPT Assinatura').first().json;
const parseData = prev.parse_data;

let temAssinatura = true;  // default OPTIMISTA — assume ok se GPT falhar
let razao = '';

if (prev.skip_gpt) {
  razao = 'GPT skipado';
} else {
  try {
    const content = gptResp?.choices?.[0]?.message?.content || '';
    const m = content.match(/\{[\s\S]*\}/);
    if (m) {
      const parsed = JSON.parse(m[0]);
      if (typeof parsed.tem_assinatura_recepcao === 'boolean') {
        temAssinatura = parsed.tem_assinatura_recepcao;
      }
      razao = parsed.razao || '';
    }
  } catch(e) {}
}

const dados = { ...(parseData.dados_fatura || {}), tem_assinatura_recepcao: temAssinatura };
return [{ json: {
  ...parseData,
  dados_fatura: dados,
  assinatura_razao: razao
} }];
